def merge_ranges(spans):
    """Merge half-open ``[start, end)`` spans into sorted, coalesced ranges.

    Accepts an outer list or tuple whose elements are list/tuple pairs of
    exactly two integer endpoints (``bool`` excluded, arbitrary size allowed)
    with ``start <= end``. Every element is validated before empty pairs are
    dropped. Returns a new list of nonempty ``[start, end]`` lists sorted
    ascending, coalescing both overlapping and adjacent ranges. The caller's
    input is never mutated.
    """
    if not isinstance(spans, (list, tuple)):
        raise ValueError("spans must be a list or tuple")

    pairs = []
    for span in spans:
        if not isinstance(span, (list, tuple)):
            raise ValueError("each span must be a list or tuple")
        if len(span) != 2:
            raise ValueError("each span must contain exactly two endpoints")
        start, end = span
        for endpoint in (start, end):
            if isinstance(endpoint, bool) or not isinstance(endpoint, int):
                raise ValueError("endpoints must be integers (bool excluded)")
        if start > end:
            raise ValueError("span start must not exceed its end")
        pairs.append((start, end))

    pairs.sort()
    merged = []
    for start, end in pairs:
        if start == end:
            continue
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

"""Parse comma-separated tags with escapes, stripping and Unicode deduplication."""

_CONTROL_CHARS = frozenset(chr(code) for code in range(0x20)) | {"\x7f"}
_ESCAPABLE = frozenset({",", "\\"})


def parse_tags(text):
    """Return de-duplicated casefolded tags parsed from ``text``.

    Commas separate tags; a backslash escapes only a comma or a backslash.
    Invalid argument types, control characters and bad escapes raise ValueError.
    """
    if not isinstance(text, str):
        raise ValueError("tags input must be a str")

    for char in text:
        if char in _CONTROL_CHARS:
            raise ValueError("tags input must not contain control characters")

    decoded = []
    segment = []
    escaped = False
    for char in text:
        if escaped:
            if char not in _ESCAPABLE:
                raise ValueError("invalid escape sequence in tags input")
            segment.append(char)
            escaped = False
        elif char == "\\":
            escaped = True
        elif char == ",":
            decoded.append("".join(segment))
            segment = []
        else:
            segment.append(char)
    if escaped:
        raise ValueError("trailing backslash in tags input")
    decoded.append("".join(segment))

    tags = []
    seen = set()
    for segment in decoded:
        tag = segment.strip().casefold()
        if not tag or tag in seen:
            continue
        seen.add(tag)
        tags.append(tag)
    return tags

